    $entity=get_post($explicit);
    if($entity instanceof WP_Post && in_array($entity->post_type,['a3_car','a3_motorcycle'],true) && $entity->post_status==='publish') return $entity;
  }
  $q=new WP_Query([
    'post_type'=>['a3_car','a3_motorcycle'],
    'post_status'=>'publish',
    'posts_per_page'=>1,
